declare @InvariantKey varchar(64) = 'LKJLMK';
declare @CountSelect varchar(64) = 'murfn...';
execute CKCore.sInvariantRegister InvariantKey, CountSelect

declare @SQLQuery AS NVARCHAR(1500)
declare @ParameterDefinition AS NVARCHAR(500)
set @SQLQuery = 'select * from sys.tables where name = @TableName or schema_id=@id or name=@OtherString';
set @ParameterDefinition = '@TableName varchar(50), @id int, @OtherString varchar(50)'
declare @TableName varchar(50) = 'tUser';
declare @OtherString varchar(50) = 'another';
declare @AnIdentifier int = 98;
execute sp_executesql @SQLQuery, @ParameterDefinition, TableName, @AnIdentifier, OtherString

create procedure CK.sTest @i int output, @j varchar(50) output
as
begin
  set @i = @i + @i;
  set @j = @j + @j;
  return 0;
end
GO
declare @AnIdentifier int = 98;
declare @AString varchar(50) = 'string';
exec CK.sTest @i = @AnIdentifier output, @j = AString;
